const input = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
const postes = input.slice(1, 1 + n);
let substituir = 0, consertar = 0;
for (const x of postes) {
  if (x < 50) substituir++;
  else if (x < 85) consertar++;
}
console.log(substituir + " " + consertar);
